DDL.statement:
BEGIN
  FOR c IN (SELECT constraint_name FROM user_constraints WHERE table_name = 'SYS_RF_MENU' AND constraint_type IN ('P', 'U')) LOOP
    EXECUTE IMMEDIATE 'ALTER TABLE SYS_RF_MENU DROP CONSTRAINT ' || c.constraint_name || ' DROP INDEX';
  END LOOP;
  FOR i IN (SELECT index_name FROM user_indexes WHERE table_name = 'SYS_RF_MENU') LOOP
    EXECUTE IMMEDIATE 'DROP INDEX ' || i.index_name;
  END LOOP;
END;
